    internal static CssSafePropertyProfile GetPropertyProfile(ReadOnlySpan<char> name)
    {
        int index = Find(propertyNames, name);
        return index < 0
            ? CssSafePropertyProfile.Unknown : propertyProfiles[index];
    }

