    internal static int Find(string[] values, ReadOnlySpan<char> value)
    {
        int minimum = 0;
        int maximum = values.Length - 1;
        while (minimum <= maximum)
        {
            int middle = minimum + (maximum - minimum) / 2;
            int comparison = Compare(value, values[middle]);
            if (comparison == 0)
            {
                return middle;
            }

            if (comparison < 0)
            {
                maximum = middle - 1;
            }
            else
            {
                minimum = middle + 1;
            }
        }

        return -1;
    }

    internal static int Compare(ReadOnlySpan<char> value, string candidate)
    {
        int count = value.Length < candidate.Length ? value.Length : candidate.Length;
        int index = 0;
        while (index < count)
        {
            char left = Ascii.ToLower(value[index]);
            char right = candidate[index];
            if (left < right)
            {
                return -1;
            }

            if (left > right)
            {
                return 1;
            }

            index = index + 1;
        }

        if (value.Length < candidate.Length)
        {
            return -1;
        }

        if (value.Length > candidate.Length)
        {
            return 1;
        }

        return 0;
    }

    internal static string[] Copy(string[] values)
    {
        string[] result = new string[values.Length];
        Array.Copy(values, result, values.Length);
        return result;
    }
